219: export function buildStreamItems(
220:   messages: Message[],
221:   opts: { liveTurnActive?: boolean } = {},
222: ): StreamItem[] {
223:   const filtered = messages.filter((m) => !isHiddenTool(m));
224:   const level1 = foldAdjacentTools(filtered);
225:   return foldTurnProcess(level1, opts.liveTurnActive ?? false);
226: }
