228: /**

330: function foldAdjacentTools(messages: Message[]): Array<Message | ToolGroup> {
331:   const out: Array<Message | ToolGroup> = [];
332: 
333:   // Items being collected for the current run. The run always opens
334:   // with a tool; once it has ≥2 tools we emit a ToolGroup, otherwise
335:   // we splay the buffer back into `out` so a single tool stays a plain
336:   // ToolMessage row (matches pre-existing behavior).
337:   let buf: ToolGroupItem[] = [];
338: 
339:   const toolCountInBuf = (): number => buf.reduce((n, it) => (it.kind === "tool" ? n + 1 : n), 0);
340: 
341:   // Drop any trailing transparent items hanging off the end of the
342:   // run — a run must end on a tool, not on thinking. Those
343:   // trailing items get pushed back to `out` so they render inline.
344:   const dropTrailingTransparent = (): ToolGroupItem[] => {
345:     const trailing: ToolGroupItem[] = [];
346:     while (buf.length > 0 && buf[buf.length - 1]!.kind !== "tool") {
347:       trailing.unshift(buf.pop()!);
348:     }
349:     return trailing;
350:   };
351: 
352:   const flushRun = (): void => {
353:     if (buf.length === 0) return;
354:     const trailing = dropTrailingTransparent();
355:     if (toolCountInBuf() >= 2) {
356:       const firstTool = buf.find((it) => it.kind === "tool") as ToolMessage;
357:       out.push({
358:         kind: "tool_group",
359:         id: `group-${firstTool.id}`,
360:         items: buf,
361:       });
362:     } else {
363:       // Single tool (with possibly some transparent items wedged in)
364:       // — splay everything back so it renders inline.
365:       for (const it of buf) out.push(it);
366:     }
367:     for (const it of trailing) out.push(it);
368:     buf = [];
369:   };
370: 
371:   for (let i = 0; i < messages.length; i++) {
372:     const m = messages[i]!;
373:     if (m.kind === "tool") {
374:       buf.push(m);
375:       continue;
376:     }
377:     if (buf.length > 0 && isTransparent(m) && nextNonTransparentIsTool(messages, i + 1)) {
378:       // Absorb the transparent item — another tool is coming before
379:       // any hard break, so this is just inline model chatter inside
380:       // an otherwise contiguous run.
381:       buf.push(m);
382:       continue;
383:     }
384:     flushRun();
385:     out.push(m);
386:   }
387:   flushRun();
388:   return out;
389: }
