391: // ── Level 2: per-turn process group ───────────────────────────────────
392: 
393: /**
394:  * Walk items from each `user` message forward. A turn that contains at
395:  * least one tool collapses into ONE TurnProcessGroup spanning from the
396:  * item right after the `user` message through the LAST tool of the turn.
397:  * That outer card holds everything in between — lead-in text, mid-run
398:  * narration, thinking, and the level-1 tool groups — so a turn reads as
399:  * a single "已处理 …" card.
400:  *
401:  * Two things stay OUTSIDE the card:
402:  *   - the `user` bubble itself (it anchors the turn);
403:  *   - the final summary text AFTER the last tool (the assistant's answer
404:  *     to the user, which should remain plainly visible).
405:  *
406:  * A turn with no tools (purely conversational) emits its items inline —
407:  * no empty "已处理 0s" card.
408:  *
409:  * The most recent turn is marked `isLive: true` while the engine is
410:  * streaming; for it the span extends to the end of the turn so in-flight
411:  * trailing text stays inside the card until the next user message lands.
412:  */
413: function foldTurnProcess(items: Array<Message | ToolGroup>, liveTurnActive: boolean): StreamItem[] {
414:   // Turn boundaries are USER messages — but NOT engine-injected ones. A steer /
415:   // goal wakeup / cron续接 splices in a user message with injected:true; that is
416:   // a continuation of the CURRENT turn, not a new user-initiated turn. Counting
417:   // it as a boundary would move `lastTurnStart` forward and demote the prior
418:   // (still-streaming) turn from isLive→false, folding it mid-flight. So injected
419:   // user messages are NOT boundaries: they fall inside the preceding turn's slice
420:   // and render inline as a user bubble there.
421:   // A non-injected user message is always a turn boundary. An injected one
422:   // (steer / goal wakeup / cron续接) usually is NOT — it continues the current
423:   // turn (see the comment above). EXCEPTION: a wakeup that arrives AFTER the
424:   // prior turn already finished (a done assistant sits before it) is really the
425:   // start of NEW work; treating it as a boundary keeps that new streaming work
426:   // live instead of folding it into the completed prior turn's card.
427:   const userIdxs: number[] = [];
428:   for (let i = 0; i < items.length; i++) {
429:     const it = items[i]!;
430:     if (it.kind !== "user") continue;
431:     const injected = it.injected === true || isSystemReminderText(it.text);
432:     if (!injected) {
433:       userIdxs.push(i);
434:       continue;
435:     }
436:     if (it.steerId) continue;
437:     // Injected: only a boundary if a done assistant precedes it since the last
438:     // real boundary (i.e. the prior turn completed before this wakeup).
439:     const priorStart = userIdxs.length ? userIdxs[userIdxs.length - 1]! : -1;
440:     if (turnHasCompleted(items, priorStart, i)) userIdxs.push(i);
441:   }
442:   if (userIdxs.length === 0) return items.slice();
443: 
444:   // Only the most recent turn can be "live", AND only while the
445:   // engine is actively streaming. Once turn_complete fires the
446:   // ticker should stop and the card becomes a normal closed group.
447:   const lastTurnStart = userIdxs[userIdxs.length - 1]!;
448: 
449:   const out: StreamItem[] = [];
450:   // Keep durable session-preface items before the first user turn. Summary
451:   // forks begin with a context_transfer card; dropping this prefix made the
452:   // forwarded context disappear as soon as the user sent the first message.
453:   for (let i = 0; i < userIdxs[0]!; i++) out.push(items[i]!);
454:   for (let k = 0; k < userIdxs.length; k++) {
455:     const start = userIdxs[k]!;
456:     const end = k + 1 < userIdxs.length ? userIdxs[k + 1]! : items.length;
457:     const isLive =
458:       liveTurnActive && start === lastTurnStart && !turnHasCompleted(items, start, end);
459:     // A turn the user interrupted carries a trailing turn_end reason="stopped"
460:     // (a flat sibling after the last tool). Such a turn must render flat, not
461:     // behind the elapsed-time fold header.
462:     const stopped = turnWasStopped(items, start, end);
463: 
464:     // user bubble stays outside the card.
465:     out.push(items[start]!);
466: 
467:     // Find the last tool-bearing item within (start, end). Bookkeeping-only
468:     // toolish items (e.g. a trailing UpdateAutomationMemory) are skipped so
469:     // they don't anchor the card's tail and swallow the report text that
470:     // precedes them — that text then stays inline after the real last tool.
471:     let lastTool = -1;
472:     for (let i = start + 1; i < end; i++) {
473:       if (isToolish(items[i]!) && !isBookkeepingToolish(items[i]!)) lastTool = i;
474:     }
475: 
476:     if (lastTool < 0) {
477:       // No tools in this turn → render everything inline (live turn
478:       // before any tool fires, or a purely conversational turn).
479:       for (let i = start + 1; i < end; i++) out.push(items[i]!);
480:       continue;
481:     }
482: 
483:     // Card spans [start+1 .. lastTool] for closed turns. For the live
484:     // turn we extend to `end` so in-flight trailing chatter stays inside
485:     // the card until the next user message solidifies the summary.
486:     const innerEnd = isLive ? end : lastTool + 1;
487:     const innerItems = items.slice(start + 1, innerEnd);
488:     const turnItems = items.slice(start, end);
489:     const user = items[start]!;
490:     const timing = user.kind === "user" ? user.turnTiming : undefined;
491:     // Closed-turn duration is the WHOLE turn's wall time, not just the tool
492:     // span: a turn whose tools each return instantly (a 0ms Skill, fast local
493:     // reads) still spent real time in the model. Prefer the user→assistant
494:     // stamp span over the slice [start..end) (which includes the trailing
495:     // summary that lives outside innerItems), and never report less than the
496:     // actual tool span. Replayed transcripts carry no stamps → tool span only.
497:     out.push({
498:       kind: "turn_process_group",
499:       id: `process-${anchorId(innerItems[0]!)}`,
500:       durationMs: isLive ? 0 : (validStamp(timing?.durationMs) ?? turnSpanMs(turnItems)),
501:       startedAt: validToolStamp(timing?.startedAt) ?? turnStartMs(turnItems),
502:       firstToolStartedAt: firstToolStart(innerItems),
503:       isLive,
504:       completedCleanly:
505:         timing?.completedCleanly ?? !turnItems.some((item) => item.kind === "turn_end"),
506:       toolCount: countToolsRecursive(innerItems),

426:   const prevItemsRef = useRef<StreamItem[]>([]);
427:   const items = useMemo(
428:     () =>
429:       timePhase(
430:         "stream.build",
431:         () => {
432:           const built = buildStreamItems(messages, { liveTurnActive });
433:           const reconciled = reconcileStreamItems(prevItemsRef.current, built);
434:           prevItemsRef.current = reconciled;
435:           // Post-pass: collapse runs of ≥2 sibling sub-agents into a summary
436:           // card. Runs after reconcile so it reads the latest AgentMessage
437:           // refs and a live agent's rollup stats stay fresh each rebuild.
438:           return foldAgentGroups(reconciled);
439:         },
440:         () => ({ msgs: messages.length }),
441:       ),
442:     [messages, liveTurnActive],
443:   );
444:   const displayGroups = useMemo(
445:     () => alignContextSelectionGroups(groupStreamItemsIntoContextTurns(items), selectionTurns),
446:     [items, selectionTurns],
447:   );
448:   const selectionAligned = displayGroups !== null;
449: 
450:   const renderStreamItem = (m: RenderedStreamItem): React.ReactNode => {
451:     if (m.kind === "turn_process_group") {
452:       return (
453:         <TurnProcessGroupCard
454:           key={m.id}
455:           group={m}
456:           turnEpoch={turnEpoch}
457:           cwd={cwd}
458:           sessionId={localRuntime ? engineSessionId : undefined}
459:           sessionMainRootId={rootId}
460:           rootStatus={rootStatus}
461:         />
462:       );
463:     }
464:     if (m.kind === "tool_group") {
465:       return (
466:         <ToolGroupCard
467:           key={m.id}
468:           group={m}
469:           turnEpoch={turnEpoch}
470:           cwd={cwd}
471:           sessionId={localRuntime ? engineSessionId : undefined}
472:           sessionMainRootId={rootId}
473:           rootStatus={rootStatus}
474:         />
